begin;
-- Add missing exam word help; preserve all existing reviewed meanings/profiles.
insert into public.englishsuccess_words(word,thai_gloss,word_profile,corpus_count,corpus_rank)
select word,thai_gloss,word_profile,0,null from jsonb_to_recordset($examwords$[{"word":"holds","thai_gloss":"จับ / ยึด; holds up = รองรับ","word_profile":{"usage_frames":[],"nouns":[],"verbs":[{"base":"hold","third":"holds","past":"held","participle":"held","ing":"holding"}],"before":[{"word":"what","count":1}],"after":[{"word":"up","count":1}],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"closing","thai_gloss":"กำลังปิด","word_profile":{"usage_frames":[],"nouns":[],"verbs":[{"base":"close","third":"closes","past":"closed","participle":"closed","ing":"closing"}],"before":[{"word":"door","count":1}],"after":[],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"rules","thai_gloss":"กติกา / กฎ","word_profile":{"usage_frames":[{"word":"rule","before":["the","my","your","this"],"after":["is","was"],"source":"teaching"},{"word":"rules","before":["the","my","your","these"],"after":["are","were"],"source":"teaching"}],"nouns":[{"singular":"rule","plural":"rules","countability":"countable"}],"verbs":[],"before":[{"word":"with","count":1}],"after":[{"word":"for","count":1}],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"cards","thai_gloss":"ไพ่ / บัตร","word_profile":{"usage_frames":[{"word":"card","before":["the","my","your","this"],"after":["is","was"],"source":"teaching"},{"word":"cards","before":["the","my","your","these"],"after":["are","were"],"source":"teaching"}],"nouns":[{"singular":"card","plural":"cards","countability":"countable"}],"verbs":[],"before":[{"word":"play","count":1}],"after":[{"word":"for","count":1}],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"thirty","thai_gloss":"สามสิบ","word_profile":{"usage_frames":[],"nouns":[],"verbs":[],"before":[],"after":[{"word":"minutes","count":1}],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"true","thai_gloss":"จริง / ถูกต้อง","word_profile":{"usage_frames":[],"nouns":[],"verbs":[],"before":[{"word":"this","count":1}],"after":[],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"choice","thai_gloss":"ทางเลือก","word_profile":{"usage_frames":[{"word":"choice","before":["the","my","your","this"],"after":["is","was"],"source":"teaching"},{"word":"choices","before":["the","my","your","these"],"after":["are","were"],"source":"teaching"}],"nouns":[{"singular":"choice","plural":"choices","countability":"countable"}],"verbs":[],"before":[{"word":"good","count":1}],"after":[{"word":"when","count":1}],"occurrences":1,"corpus_version":"exam-ch34-v1"}}]$examwords$::jsonb) as r(word text,thai_gloss text,word_profile jsonb)
on conflict(word) do update set thai_gloss=coalesce(englishsuccess_words.thai_gloss,excluded.thai_gloss),word_profile=coalesce(englishsuccess_words.word_profile,excluded.word_profile);
commit;
